#include "finite.hpp"
int main(int argc,char**argv){try{ec::check(argc==3,"workload outdir");Graph graph(argv[1]);ec::check(graph.w.h.nodes>512,"publication fixture nodes");std::filesystem::create_directories(argv[2]);auto m=std::make_unique<ec::Model>(graph,0,argv[2]);auto&b=m->b(0);for(unsigned i=0;i<3;++i){auto&x=b.tx[i];x.state=ec::Tx::EVENT;x.node=i*256;x.op=7;x.due=1000;x.append=i==0?15:0;x.newpv.fill(65537);x.next.p.fill(0);b.txmask|=1u<<i;}m->t=1000;ec::T previous=0;unsigned previous_events=0;std::vector<ec::T>retirement;bool block_checked=false,reuse_checked=false;for(unsigned k=0;k<20;++k){m->memory_begin();m->canonical();ec::check(b.retired-previous<=1,"MULTIPLE_COMPLETIONS_PER_BANK_CLOCK");ec::check(m->directory.used-previous_events<=1,"MULTIPLE_DIRECTORY_WRITES");if(b.retired!=previous){retirement.push_back(m->t);if(retirement.size()==1){ec::check(m->directory.used==4,"HELD_BUNDLE_NOT_DRAINED");ec::check(!m->start_tx(0,0,7,0,ec::PairLine{}),"SAME_EDGE_WORD_REUSE");block_checked=true;}}if(block_checked&&!reuse_checked&&m->t==retirement.front()+1){ec::check(m->start_tx(0,0,7,0,ec::PairLine{}),"NEXT_EDGE_WORD_NOT_REUSABLE");reuse_checked=true;}previous=b.retired;previous_events=m->directory.used;++m->t;if(retirement.size()==3)break;}ec::check(retirement==std::vector<ec::T>{1005,1006,1007},"PUBLICATION_EDGE_SEQUENCE");ec::check(block_checked&&reuse_checked,"WORD_REUSE_TEST_COVERAGE");std::cout<<"PUBLICATION_TEST_PASS held4events_then2zeroevent_bundles retire=1005,1006,1007 nextedge_word_reuse\n";}catch(std::exception&e){std::cerr<<e.what()<<'\n';return 1;}return 0;}
